def retrieve(principal, query, query_vector, chunks):
    authorized = [c for c in chunks if c.tenant_id == principal.tenant_id and (not c.allowed_users or principal.subject in c.allowed_users)]
    lexical = bm25_scores(query, authorized)
    dense = {c.chunk_id: cosine_similarity(query_vector, c.embedding) for c in authorized}
    lexical_rank = sorted((k for k,v in lexical.items() if v > 0), key=lambda k: (-lexical[k], k))
    dense_rank = sorted((k for k,v in dense.items() if v > 0), key=lambda k: (-dense[k], k))
    fused = reciprocal_rank_fusion([lexical_rank, dense_rank])
    return sorted(fused, key=lambda k: (-fused[k], k))
